import { afterEach, describe, expect, it, vi } from "vitest";
import { cleanup, fireEvent, render, screen, waitFor, within } from "@testing-library/react";
import { App } from "../../src/App";
import { formConfig, stubBackend } from "./support";

const PRIVACY = formConfig.consents[0].text;
const PHOTO = formConfig.consents[1].text;

afterEach(() => {
  cleanup();
  vi.unstubAllGlobals();
});

async function renderLoaded() {
  render(<App />);
  await screen.findByRole("heading", { level: 1, name: /Konferenca 2026/ });
}

function type(label: string, value: string) {
  fireEvent.change(screen.getByLabelText(label), { target: { value } });
}

function fillValidExternal() {
  type("First name", "Ana");
  type("Last name", "Novak");
  type("Email", "ana.novak@example.test");
  type("Organization / institution", "Institut Jožef Stefan");
  fireEvent.click(screen.getByRole("checkbox", { name: "Workshop: AI v praksi" }));
  fireEvent.click(screen.getByRole("checkbox", { name: PRIVACY }));
}

describe("US-001 external participant form", () => {
  it("AC-001-08: shows the external fields, active options by category and unchecked consents", async () => {
    stubBackend({ status: 201 });
    await renderLoaded();

    const typeGroup = screen.getByRole("radiogroup", { name: "Registration type" });
    expect(within(typeGroup).getByRole("radio", { name: "External participant" })).toBeChecked();
    expect(within(typeGroup).getByRole("radio", { name: "Student" })).not.toBeChecked();

