      {errors.captchaToken && <p className="error">{errors.captchaToken}</p>}

      {general && (
        <p role="alert" className="alert">
          {general}
        </p>
      )}
      <button type="submit" disabled={submitting}>
        Register
      </button>
    </form>
  );
}

